def-struct-hyp(
    __list__(
        Type.annotation(@T, Type),
        Type.annotation(@S, Set(T)),
        Type.annotation(@τ, Set(S))
    ),
    Topology.topology(τ, S@Topology.ctxt.S),
    __enum__(
        member[colon](%包含全集和空集%, Logic.and(Set.mem(S@Topology.ctxt.S, τ), Set.mem(Set.emptyset, τ))),
        member[colon](
            %对任意并封闭%,
            Logic.forall-typed(
                @$\mathcal{O}$,
                Set(S),
                Logic.implies(
                    Set.subset($\mathcal{O}$, τ),
                    Set.mem(
                        Set.sep-typed(
                            @x,
                            S@Topology.ctxt.S,
                            Logic.exists-typed(@U, Set(T), Logic.and(Set.mem(U, $\mathcal{O}$), Set.mem(x, U)))
                        ),
                        τ
                    )
                )
            )
        ),
        member[colon](
            %对有限交封闭%,
            Logic.forall-typed(
                @U,
                Set(T),
                Logic.forall-typed(
                    @V,
                    Set(T),
                    Logic.implies(Logic.and(Set.mem(U, τ), Set.mem(V, τ)), Set.mem(Set.inter(U, V), τ))
                )
            )
        )
    )
)
